@Component("measure-handler")
@ProcessingGroup("measure-processing-group")
public class MeasureEventHandler {
	
	// core constructor
	MeasureEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateMeasureEvent
     */
    @EventHandler
    public void handle( CreateMeasureEvent event) {
        entityManager.persist(new Measure(event.getMeasureId(), event.getName(), event.getFormat(), event.getSemanticModel(), event.getDatasets(), event.getGlossaryTerms(), event.getAggregation()));
    }

    /*
     * @param	event UpdateMeasureEvent
     */
    @EventHandler
    public Measure handle( UpdateMeasureEvent event) {
    	entityManager.merge(new Measure(event.getMeasureId(), event.getName(), event.getFormat(), event.getSemanticModel(), event.getDatasets(), event.getGlossaryTerms(), event.getAggregation()));
    }
    
    /*
     * @param	event DeleteMeasureEvent
     */
    @EventHandler
    public void on( DeleteMeasureEvent event) {
    	Measure entity = new Measure();
   
    	// ------------------------------------------
    	// apply the MeasureId
    	// ------------------------------------------
    	entity.setMeasureId( event.getMeasureId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final MeasureRepository measureEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(MeasureEventHandler.class.getName());

}
